function sanitizeArticle(a){let modern=a.statusVersion===2||['neutral','fetched'].includes(a.status),previous=a.previousStatus;return {id:String(a.id||uid()),nr:String(a.nr),description:String(a.description||''),status:modern&&labels[a.status]?a.status:'neutral',statusVersion:2,blockReason:String(a.blockReason||'').slice(0,1000),previousStatus:previous&&typeof previous==='object'?{status:String(previous.status||''),updated:Number(previous.updated)||0}:!modern&&a.status?{status:String(a.status),updated:Number(a.updated)||0}:null,location:String(a.location||''),note:String(a.note||''),updated:Number(a.updated)||Date.now(),isGroup:!!a.isGroup,requiredQty:optionalNumber(a.requiredQty),perUnitQty:optionalNumber(a.perUnitQty),availableQty:optionalNumber(a.availableQty),shortageQty:optionalNumber(a.shortageQty),unit:String(a.unit||'')};}
