function changeStatus(id,status,reason){let o=current(),a=o?.articles.find(a=>a.id===id);if(!a||a.isGroup||!labels[status])return false;if(status==='found'){if(reason===undefined){pendingFound={orderId:o.id,articleId:id};$('foundReason').value=a.blockReason||'';$('foundArticle').textContent=a.nr;$('foundDialog').showModal();$('foundReason').focus();return false;}reason=String(reason).trim().slice(0,1000);if(!reason){notice('Ange varför artikeln inte kan hämtas.');return false;}a.blockReason=reason;}let was=a.status;a.status=status;a.statusVersion=2;a.updated=Date.now();o.updated=a.updated;if(['found','fetched'].includes(status)&&!['found','fetched'].includes(was))rememberFound(a,o,true);persist();return true;}
function removeArticle(id){let o=current(),a=o?.articles.find(a=>a.id===id);if(!a||!confirm(`Ta bort ${a.nr} från ordern?`))return;o.articles=o.articles.filter(x=>x.id!==id);o.updated=Date.now();(o.deletedArticles??={})[id]=o.updated;persist();}
function updateStock(key,field,value){let x=data.stock[key];if(!x)return;value=value.trim();if(field==='location'&&x.location&&norm(x.location)!==norm(value))x.previousLocations=[x.location,...(x.previousLocations||[]).filter(p=>norm(p)!==norm(x.location))].slice(0,20);x[field]=value;x.updated=Date.now();if(field==='location'){x.locationUpdated=x.updated;x.locationOrder=''}persist(false);}
function orderRows(list){return list.map(o=>{let materials=o.articles.filter(a=>!a.isGroup),missing=materials.filter(a=>a.status==='notfound').length;return '<button class="order-row '+(o.id===data.current?'selected':'')+'" data-order="'+esc(o.id)+'"><span class="line"><strong>'+esc(o.name)+'</strong><span class="count '+(missing?'has-missing':'no-missing')+'">'+missing+' saknas</span></span><small>'+(o.productName?esc(o.productName)+' · ':'')+materials.length+' artiklar · '+date(o.created)+'</small></button>';}).join('');}
