 for(const line of lineNames()){let orders=active.filter(o=>o.kind==='picklist'&&o.line===line),names=Array.from(new Map([...activeGroups(line).map(g=>g.name),...orders.map(o=>o.subgroup).filter(Boolean)].map(name=>[norm(name),name])).values());html+='<section class="line-section production-section" aria-label="'+esc(line)+'"><div class="line-section-head"><div class="line-title"><span class="section-label">PRODUKTIONSLINJE</span><h3>'+esc(line)+' <span>'+orders.length+'</span></h3></div><button type="button" class="add-subgroup" data-add-group="'+esc(line)+'" aria-label="Ny underrubrik i '+esc(line)+'">+ Typ</button></div><div class="line-content">'+orderRows(orders.filter(o=>!o.subgroup));for(const name of names){let list=orders.filter(o=>norm(o.subgroup)===norm(name));html+='<section class="subgroup-block" aria-label="'+esc(line)+' – '+esc(name)+'"><div class="subgroup-heading"><div><span class="subgroup-label">AGGREGATTYP</span><h4>'+esc(name)+'</h4></div><span>'+list.length+'</span><button type="button" data-new-in-line="'+esc(line)+'" data-new-in-group="'+esc(name)+'" aria-label="Skapa order i '+esc(name)+'">+ Order</button></div>'+orderRows(list)+(list.length?'':'<p class="subgroup-empty">Inga aktiva ordrar</p>')+'</section>';}if(!orders.length&&!names.length)html+='<p class="section-empty">Inga aktiva ordrar</p>';html+='</div></section>';}
 let unplaced=active.filter(o=>o.kind==='picklist'&&!o.line);if(unplaced.length)html+='<section class="line-section"><div class="order-section">Ej placerade · '+unplaced.length+'</div>'+orderRows(unplaced)+'</section>';
