 return `<div class="article ${a.status}" data-id="${esc(a.id)}"><div class="identity"><div class="number">${esc(a.nr)}</div>${description?`<div class="description">${esc(description)}</div>`:''}<div class="context">${esc(articleContext(a))}</div></div><div class="location"><label class="sr-only" for="loc-${esc(a.id)}">Lagerplats för ${esc(a.nr)}</label><input id="loc-${esc(a.id)}" data-field="location" value="${esc(a.location)}" placeholder="Hämta från lagerplats" autocomplete="off" autocapitalize="characters">${!a.location&&old.location?`<button class="use-known" data-use-known>Använd ${esc(old.location)}</button>`:''}</div><div class="note"><label class="sr-only" for="note-${esc(a.id)}">Anteckning för ${esc(a.nr)}</label><input id="note-${esc(a.id)}" data-field="note" value="${esc(a.note)}" placeholder="Anteckning" autocomplete="off"></div><div class="status-group ${o.kind==='picklist'?'picklist-status':''}" role="group" aria-label="Status för ${esc(a.nr)}">${Object.keys(labels).map(status=>`<button class="${status}" data-status="${status}" aria-pressed="${a.status===status}">${status==='fetched'?'✓ ':status==='notfound'?'✕ ':status==='found'?'◉ ':'— '}${statusLabel(status,o)}</button>`).join('')}</div><button class="delete" data-delete title="Ta bort ${esc(a.nr)}" aria-label="Ta bort ${esc(a.nr)}">×</button>${quantities}${a.status==='found'?'<div class="blocking-reason"><strong>Kan inte hämtas:</strong> '+esc(a.blockReason||'Ange anmärkning')+' <button class="secondary small" data-status="found">Ändra anmärkning</button></div>':''}${a.previousStatus?'<details class="previous-status"><summary>Tidigare status före nya plockflödet</summary>'+esc(({missing:'Saknas',found:'Hittad',notfound:'Inte hittad'})[a.previousStatus.status]||a.previousStatus.status)+'</details>':''}</div>`;
