function renderArticles(){
 let o=current();if(!o)return;let q=norm($('search').value),arr=sectionOrder(o).articles.filter(a=>{let x=data.stock[norm(a.nr)]||{};if(a.isGroup&&(filter!=='all'||sortBy!=='default'))return false;return(filter==='all'||a.isGroup||a.status===filter||(filter==='remaining'&&a.status!=='fetched'))&&norm([a.nr,a.description,x.description,a.location,a.note,a.blockReason,x.location,x.note,(x.previousLocations||[]).join(' ')].join(' ')).includes(q)});
 if(sortBy==='location'||sortBy==='area')arr.sort((a,b)=>{let la=a.location||data.stock[norm(a.nr)]?.location||'',lb=b.location||data.stock[norm(b.nr)]?.location||'';return !la&&!lb?0:!la?1:!lb?-1:la.localeCompare(lb,'sv',{numeric:true})});
 if(sortBy==='known')arr.sort((a,b)=>Number(!!(b.location||data.stock[norm(b.nr)]?.location))-Number(!!(a.location||data.stock[norm(a.nr)]?.location)));
 let content;if(sortBy==='area'&&arr.length){let grouped=new Map();for(const a of arr){let loc=a.location||data.stock[norm(a.nr)]?.location||'',area=loc.match(/^[\p{L}\p{N}]+/u)?.[0]||'Okänd plats';if(!grouped.has(area))grouped.set(area,[]);grouped.get(area).push(a)}content=Array.from(grouped,([area,items])=>`<div class="areahead">${esc(area)} · ${items.length}</div>`+items.map(a=>renderArticle(a,o)).join('')).join('')}else content=arr.map(a=>renderArticle(a,o)).join('');
 $('articles').innerHTML=content||'<div class="empty">Inga artiklar matchar. Prova ett annat sökord eller visa alla.</div>';document.querySelectorAll('.filters button').forEach(b=>{b.classList.toggle('selected',b.dataset.filter===filter);b.setAttribute('aria-pressed',String(b.dataset.filter===filter));});if(typeof renderWorkbench==='function')renderWorkbench(arr.filter(a=>!a.isGroup).length);
}
function renderStock(){let q=norm($('stockSearch').value),list=Object.values(data.stock).filter(x=>norm([x.nr,x.description,x.location,x.note,(x.previousLocations||[]).join(' ')].join(' ')).includes(q)).sort((a,b)=>a.nr.localeCompare(b.nr,'sv',{numeric:true}));$('stock').innerHTML=list.map(x=>{let key=norm(x.nr),previous=(x.previousLocations||[]).length?`Tidigare: ${x.previousLocations.join(', ')}`:'Ingen tidigare plats';return `<div class="stockrow" data-key="${esc(key)}"><div><b>${esc(x.nr)}</b><div class="description">${esc(x.description)}</div><small>${esc(previous)}</small></div><div><label class="sr-only">Lagerplats för ${esc(x.nr)}</label><input data-stock-field="location" value="${esc(x.location)}" placeholder="Lagerplats"></div><div><label class="sr-only">Anteckning för ${esc(x.nr)}</label><input data-stock-field="note" value="${esc(x.note)}" placeholder="Anteckning"></div><div><small>Plats sparad ${date(x.locationUpdated)}</small><small>Hittad ${x.foundCount||0} ${(x.foundCount||0)===1?'gång':'gånger'}</small>${x.lastSeen?`<small>Senast hittad ${date(x.lastSeen)}</small>`:''}<small>${x.locationOrder?'Plats från order '+esc(x.locationOrder):''}</small></div></div>`}).join('')||'<div class="empty">Inga sparade artiklar matchar.</div>';}
function renderCloud(){
 const available=window.Cloud?.available,user=window.Cloud?.user;
 $('passwordLoginForm').classList.toggle('hidden',!available||!!user);
 $('emailLogin').classList.toggle('hidden',!available||!!user);
 $('codeForm').classList.toggle('hidden',!available||!!user||!cloudEmail);
 $('setPasswordForm').classList.toggle('hidden',!user);
 $('signOut').classList.toggle('hidden',!user);
 $('syncConflict').classList.toggle('hidden',!cloudConflict);
 $('cloudStatus').textContent=available?(user?`${cloudMessage} · ${user.email||'Inloggad'}`:cloudMessage):'Molnsynk väntar på ett separat Lagerkollen-konto. Lokal backup fungerar fortfarande.';
}
function checkpoint(){try{return JSON.parse(localStorage.getItem(CHECKPOINT)||'null')}catch(e){return null}}
function markSynced(revision){cloudRevision=revision;try{localStorage.setItem(CHECKPOINT,JSON.stringify({userId:Cloud.user.id,localRevision:data._revision,remoteRevision:revision}))}catch(e){}cloudMessage='Synkad';setSaveState('Synkad');renderCloud()}
function replaceFromCloud(row){data=sanitize(row.payload);cloudRevision=row.revision;cloudConflict=null;let raw=JSON.stringify(data);try{localStorage.setItem(KEY,raw)}catch(e){notice('Kunde inte spara molndata lokalt')}writeMirror(raw).catch(()=>{});markSynced(row.revision);render()}
function hasRecords(value){return value.orders.length>0||Object.keys(value.stock).length>0||Object.keys(value.deletedOrders||{}).length>0||(value.groups||[]).length>0||(value.sections||[]).some(x=>x.updated>0||x.deleted)}
function hasLocalData(){return hasRecords(data)}
function shouldSeedCloud(row,cp,userId){return hasLocalData()&&!hasRecords(row.payload)&&(!cp?.userId||cp.userId===userId)}
function showConflict(row){cloudConflict=row;cloudMessage='Synkkonflikt – välj version i Backup & synk';setSaveState('Synkkonflikt',true);renderCloud();notice('Data finns på båda enheterna. Välj version i Backup & synk.')}
async function initCloud(){if(!window.Cloud?.available){renderCloud();return}try{let user=await Cloud.init((event)=>{if(event==='SIGNED_IN')startCloud().catch(syncError);if(event==='SIGNED_OUT'){cloudRevision=null;cloudConflict=null;cloudMessage='Utloggad – data sparas lokalt';renderCloud()}});if(user)await startCloud()}catch(e){syncError(e)}}
function syncError(e){cloudMessage='Synkfel: '+(e.message||e);setSaveState('Synkfel – lokalt sparad',true);renderCloud()}
async function startCloud(){if(!Cloud.user||cloudBusy)return;cloudBusy=true;cloudMessage='Kontrollerar molndata…';renderCloud();try{let row=await Cloud.read(),cp=checkpoint();if(!row){cloudRevision=null;cloudBusy=false;await pushCloud();return}cloudRevision=row.revision;if(shouldSeedCloud(row,cp,Cloud.user.id)){cloudBusy=false;await pushCloud();return}if(!hasLocalData()||(cp?.userId===Cloud.user.id&&cp.localRevision===data._revision)){replaceFromCloud(row)}else{showConflict(row)}}catch(e){syncError(e)}finally{cloudBusy=false}clearInterval(cloudTimer);cloudTimer=setInterval(()=>pullCloud().catch(syncError),15000)}
function scheduleCloudPush(){if(!Cloud?.user||cloudConflict)return;cloudMessage='Ändringar väntar på synk';renderCloud();clearTimeout(pushTimer);pushTimer=setTimeout(()=>pushCloud().catch(syncError),450)}
let pushTimer;
async function pushCloud(){if(!Cloud.user||cloudBusy||cloudConflict)return;cloudBusy=true;const revisionAtStart=data._revision,copy=JSON.parse(JSON.stringify(data));try{let next=await Cloud.write(copy,cloudRevision);if(next===null){let latest=await Cloud.read();if(latest)showConflict(latest);return}cloudRevision=next;if(data._revision===revisionAtStart)markSynced(next);else{try{localStorage.setItem(CHECKPOINT,JSON.stringify({userId:Cloud.user.id,localRevision:revisionAtStart,remoteRevision:next}))}catch(e){}cloudMessage='Fler ändringar väntar'}}catch(e){syncError(e)}finally{cloudBusy=false}if(data._revision!==revisionAtStart&&!cloudConflict)scheduleCloudPush()}
async function pullCloud(){if(!Cloud.user||cloudBusy||cloudConflict||document.hidden)return;let field=document.activeElement;if(field?.closest('.article,.stockrow'))return;cloudBusy=true;try{let row=await Cloud.read();if(!row){cloudRevision=null;cloudBusy=false;await pushCloud();return}if(row.revision===cloudRevision){let cp=checkpoint();if(cp?.localRevision!==data._revision){cloudBusy=false;await pushCloud()}return}let cp=checkpoint();if(cp?.userId===Cloud.user.id&&cp.localRevision===data._revision)replaceFromCloud(row);else showConflict(row)}catch(e){syncError(e)}finally{cloudBusy=false}}
function mergeData(remote,local){let result=sanitize(remote);local=sanitize(local);result.deletedOrders=Object.fromEntries(Array.from(new Set([...Object.keys(result.deletedOrders),...Object.keys(local.deletedOrders)])).map(id=>[id,Math.max(result.deletedOrders[id]||0,local.deletedOrders[id]||0)]));result.sections=mergeSections(result.sections,local.sections);result.groups=mergeGroups(result.groups,local.groups);let orders=new Map(result.orders.map(o=>[o.id,o]));for(const incoming of local.orders){if(Object.hasOwn(result.deletedOrders,incoming.id))continue;let existing=orders.get(incoming.id);if(!existing){orders.set(incoming.id,incoming);continue}let byId=new Map(existing.articles.map(a=>[a.id,a]));for(const article of incoming.articles){let prior=byId.get(article.id);if(!prior||article.updated>prior.updated)byId.set(article.id,mergeArticle(prior,article))}existing.deletedArticles={...existing.deletedArticles};for(const [id,time] of Object.entries(incoming.deletedArticles||{}))existing.deletedArticles[id]=Math.max(existing.deletedArticles[id]||0,time);existing.articles=Array.from(byId.values()).filter(a=>a.updated>(existing.deletedArticles[a.id]||0));if(incoming.updated>existing.updated){Object.assign(existing,{name:incoming.name,line:incoming.line,subgroup:incoming.subgroup,kind:existing.kind==='picklist'?existing.kind:incoming.kind,productName:incoming.productName||existing.productName,productNr:incoming.productNr||existing.productNr,productionQty:incoming.productionQty??existing.productionQty,printedAt:incoming.printedAt||existing.printedAt,archived:incoming.archived,updated:incoming.updated})}}result.orders=Array.from(orders.values()).filter(o=>!Object.hasOwn(result.deletedOrders,o.id)).map(normalizePicklist).sort((a,b)=>b.created-a.created);for(const [key,x] of Object.entries(local.stock)){let prior=result.stock[key];if(!prior||x.updated>prior.updated){result.stock[key]={...x,previousLocations:Array.from(new Set([...(x.previousLocations||[]),...(prior?.previousLocations||[])]))}}else{prior.previousLocations=Array.from(new Set([...(prior.previousLocations||[]),...(x.previousLocations||[])]))}}result.current=result.orders.some(o=>o.id===local.current)?local.current:(result.orders.some(o=>o.id===result.current)?result.current:(result.orders.find(o=>!o.archived)||result.orders[0]||{}).id||null);return reconcilePlacement(result)}
function render(){refreshLineChoices();renderEditor();renderOrders();renderOrder();renderStock();renderCloud();$('backupMeta').textContent=`${data.orders.length} ordrar · ${Object.keys(data.stock).length} registerartiklar`;}
