$('sectionForm').onsubmit=e=>{e.preventDefault();if(addSection($('sectionName').value))$('sectionName').value='';};
$('headingEditor').addEventListener('submit',e=>{let form=e.target.closest('[data-add-heading]');if(!form)return;e.preventDefault();let name=form.elements.heading.value;if(headingName(name)){ensureGroup(form.dataset.addHeading,name);persist();notice('Underrubrik tillagd');}});
$('headingEditor').onclick=e=>{let rename=e.target.closest('[data-rename-heading]'),remove=e.target.closest('[data-delete-heading]');if(rename){let next=prompt('Nytt namn:',rename.dataset.headingName||rename.dataset.renameHeading);if(next!==null)renameHeading(rename.dataset.renameHeading,rename.dataset.headingName,next);}if(remove)deleteHeading(remove.dataset.deleteHeading,remove.dataset.headingName);};
$('orderLine').onchange=()=>{$('orderGroup').value='';refreshGroupChoices();};
$('placementLine').onchange=()=>fillGroupSelect('placementGroup',$('placementLine').value);
$('placementForm').onsubmit=e=>{e.preventDefault();placeOrder($('placementLine').value,$('placementGroup').value)};
$('deleteOrder').onclick=()=>{if(current())removeOrder(current().id)};
$('orders').onclick=e=>{let b=e.target.closest('[data-order]');if(b){selectOrder(b.dataset.order);return}let group=e.target.closest('[data-add-group]');if(group){let name=prompt('Ny underrubrik i '+group.dataset.addGroup+' (t.ex. Cup, Magma eller Rondo):');if(name?.trim()){ensureGroup(group.dataset.addGroup,name);persist()}return}let create=e.target.closest('[data-new-in-line]');if(create){startOrder();$('orderLine').value=create.dataset.newInLine;refreshGroupChoices();$('orderGroup').value=create.dataset.newInGroup;}};document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>show(b.dataset.view));$('toggleOrders').onclick=()=>show('orders');$('openBackup').onclick=()=>show('backup');$('stockBack').onclick=$('backupBack').onclick=$('editBack').onclick=()=>show('order');
let pendingRepeat=null;
$('repeatOrder').onclick=()=>{let o=current();if(!o)return;pendingRepeat=o.id;$('repeatName').value=o.name;$('repeatQty').value=o.productionQty??'';$('repeatDialog').showModal();$('repeatName').focus();};
$('repeatForm').onsubmit=e=>{e.preventDefault();if(current()?.id!==pendingRepeat){$('repeatDialog').close();notice('Ordern ändrades. Öppna Kör igen på nytt.');return;}let raw=$('repeatQty').value,qty=optionalNumber(raw);if(raw!==''&&(!(qty>0))){notice('Ange ett antal större än noll.');return;}if(repeatOrder($('repeatName').value,qty))$('repeatDialog').close();};
$('repeatCancel').onclick=()=>$('repeatDialog').close();$('repeatDialog').addEventListener('close',()=>{pendingRepeat=null;});
$('articleSection').onchange=e=>{sectionFilter=e.target.value;renderOrder();};
$('archive').onclick=()=>{let o=current();if(!o)return;o.archived=!o.archived;o.updated=Date.now();persist();notice(o.archived?'Order arkiverad':'Order återöppnad')};
$('copyResults').onclick=async()=>{let order=current();if(!order?.articles.length)return;try{await copyText(formatOrderResults(order));notice(`${order.articles.filter(a=>!a.isGroup).length} ${order.articles.filter(a=>!a.isGroup).length===1?'artikel kopierad':'artiklar kopierade'}. Klistra in i Excel eller ett meddelande.`)}catch(e){notice('Kunde inte kopiera. Prova i Safari eller Chrome.')}};
$('quickAdd').onclick=()=>{if(addArticles($('quickInput').value))$('quickInput').value='';$('quickInput').focus()};$('quickInput').onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();$('quickAdd').click()}};
$('entryToggle').onclick=()=>{let hidden=$('bulkEntry').classList.toggle('hidden');$('entryToggle').setAttribute('aria-expanded',String(!hidden));if(!hidden)$('paste').focus()};$('add').onclick=()=>{if(addArticles($('paste').value))$('paste').value=''};
$('articleFile').onchange=async e=>{let file=e.target.files?.[0];if(!file)return;try{if(file.size>2e6)throw Error('Filen är för stor (max 2 MB)');let raw=await file.text(),parsed=extract(raw);$('paste').value=raw;$('importPreview').textContent=`${parsed.values.length} möjliga nummer. Granska texten och tryck Lägg till nummer.`;$('bulkEntry').classList.remove('hidden');$('entryToggle').setAttribute('aria-expanded','true')}catch(err){notice(err.message)}e.target.value=''};
$('search').oninput=renderArticles;$('stockSearch').oninput=renderStock;$('sort').onchange=e=>{sortBy=e.target.value;renderArticles()};document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;renderArticles()});
$('articles').onclick=e=>{let row=e.target.closest('.article');if(!row)return;let s=e.target.closest('[data-status]');if(s)changeStatus(row.dataset.id,s.dataset.status);if(e.target.closest('[data-delete]'))removeArticle(row.dataset.id);if(e.target.closest('[data-use-known]')){let a=current()?.articles.find(a=>a.id===row.dataset.id);if(a)saveField(a.id,'location',data.stock[norm(a.nr)]?.location||'');renderArticles()}};
$('articles').addEventListener('keydown',e=>{if(e.key!=='Enter'||e.target.dataset.field!=='location')return;e.preventDefault();let fields=Array.from(document.querySelectorAll('#articles [data-field=location]')),index=fields.indexOf(e.target),id=e.target.closest('.article').dataset.id;saveField(id,'location',e.target.value);if(fields[index+1])fields[index+1].focus();else e.target.blur()});
$('articles').addEventListener('change',e=>{let row=e.target.closest('.article'),field=e.target.dataset.field;if(row&&['location','note'].includes(field))saveField(row.dataset.id,field,e.target.value)});$('stock').addEventListener('change',e=>{let row=e.target.closest('[data-key]'),field=e.target.dataset.stockField;if(row&&['location','note'].includes(field))updateStock(row.dataset.key,field,e.target.value)});
$('passwordLoginForm').onsubmit=async e=>{e.preventDefault();let email=$('passwordEmail').value.trim(),password=$('passwordLogin').value;$('email').value=email;try{await Cloud.signInWithPassword(email,password);$('passwordLogin').value='';cloudMessage='Loggar in…';renderCloud()}catch(err){$('passwordLogin').value='';syncError(err.message==='Invalid login credentials'?Error('Fel e-post eller lösenord. Använd mejllänk om du behöver skapa ett lösenord.'):err)}};
$('loginForm').onsubmit=async e=>{e.preventDefault();cloudEmail=$('email').value.trim();try{await Cloud.sendLink(cloudEmail);cloudMessage='Kontrollera mejlen och öppna länken på denna enhet. Om mejlet innehåller en kod kan du ange den här.';renderCloud()}catch(err){syncError(err)}};
$('codeForm').onsubmit=async e=>{e.preventDefault();try{await Cloud.verifyCode(cloudEmail||$('email').value.trim(),$('code').value.trim());$('code').value=''}catch(err){syncError(err)}};
$('setPasswordForm').onsubmit=async e=>{e.preventDefault();let password=$('newPassword').value;if(password!==$('confirmPassword').value){notice('Lösenorden matchar inte');return}try{await Cloud.setPassword(password);$('newPassword').value='';$('confirmPassword').value='';notice('Lösenord sparat. Logga in med det på dina andra enheter.')}catch(err){syncError(err)}};
$('signOut').onclick=()=>Cloud.signOut().catch(syncError);
$('useCloud').onclick=()=>{if(!cloudConflict)return;if(!confirm('Ersätta denna enhets data med molnversionen? Exportera en backup först om lokala ändringar ska sparas.'))return;replaceFromCloud(cloudConflict)};
$('mergeCloud').onclick=()=>{if(!cloudConflict)return;let merged=mergeData(cloudConflict.payload,data);cloudRevision=cloudConflict.revision;cloudConflict=null;data=merged;persist();notice('Data sammanslagen och synkas till molnet')};
window.addEventListener('online',()=>pullCloud().catch(syncError));document.addEventListener('visibilitychange',()=>{if(!document.hidden)pullCloud().catch(syncError)});
$('export').onclick=()=>{let blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='lagerkollen-backup-'+new Date().toISOString().slice(0,10)+'.json';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000)};
$('import').onchange=async e=>{let file=e.target.files?.[0];if(!file)return;try{if(file.size>20e6)throw Error('Backupen är för stor');let imported=sanitize(JSON.parse(await file.text()));if(confirm(`Ersätta nuvarande data med ${imported.orders.length} ordrar och ${Object.keys(imported.stock).length} registerartiklar? Exportera gärna nuvarande data först.`)){data=imported;persist();show('order');notice('Backup importerad')}}catch(err){notice('Ogiltig backup: '+err.message)}e.target.value=''};
document.addEventListener('keydown',e=>{let typing=e.target.matches('input,textarea,select,[contenteditable]');if(e.key==='Escape'&&e.target===$('search')){$('search').value='';renderArticles();$('search').blur()}if(typing||e.ctrlKey||e.metaKey||e.altKey)return;if(e.key==='/'){e.preventDefault();show('order');$('search').focus()}if(e.key.toLowerCase()==='n'){e.preventDefault();show('order');$('quickInput').focus()}});
window.addEventListener('storage',e=>{if(e.key!==KEY||!e.newValue)return;try{let incoming=sanitize(JSON.parse(e.newValue));if(incoming._revision>data._revision){data=incoming;render();notice('Ändringar från en annan flik laddades')}}catch(err){}});
boot();if('serviceWorker'in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('/sw.js').catch(()=>{}));
